async function fetchRecyclerPrices(keyword, isActive) {
	try {
		const params = new URLSearchParams();
		if (keyword) params.append("keyword", keyword);
		if (typeof isActive === "boolean") params.append("isActive", String(isActive));
		const res = await authorizedRequest("recycler", `/api/v1/recycler/prices${params.toString() ? `?${params.toString()}` : ""}`, { method: "GET" });
		if (Array.isArray(res.data)) return {
			items: res.data,
			fromBackend: true
		};
	} catch {}
	const state = readSyncState();
	if (state.customPrices && state.customPrices.length > 0) {
		let filtered = state.customPrices;
		if (typeof isActive === "boolean") filtered = filtered.filter((p) => p.isActive === isActive);
		if (keyword) {
			const kw = keyword.toLowerCase();
			filtered = filtered.filter((p) => p.wasteCategoryName.toLowerCase().includes(kw) || p.wasteCategoryCode.toLowerCase().includes(kw));
		}
		return {
			items: filtered,
			fromBackend: false
		};
	}
	return {
		items: [],
		fromBackend: false
	};
}
async function saveRecyclerPrices(items) {
	try {
		const res = await authorizedRequest("recycler", "/api/v1/recycler/prices", {
			method: "PUT",
			body: JSON.stringify({ items })
		});
		if (Array.isArray(res.data)) {
			writeSyncState({
				...readSyncState(),
				customPrices: res.data
			});
			return {
				items: res.data,
				syncedWithBackend: true
			};
		}
	} catch {}
	const now = (/* @__PURE__ */ new Date()).toISOString();
	const localItems = items.map((it, idx) => ({
		id: `local-price-${idx + 1}`,
		wasteCategoryId: it.wasteCategoryId,
		wasteCategoryCode: it.wasteCategoryId.slice(0, 8),
		wasteCategoryName: it.wasteCategoryId,
		pricePerKg: it.pricePerKg,
		minQuantityKg: it.minQuantityKg ?? 1,
		collectionConditions: it.collectionConditions ?? null,
		isActive: it.isActive,
		effectiveFrom: now,
		effectiveTo: null,
		lastUpdatedAt: now,
		isOutdated: false
	}));
	writeSyncState({
		...readSyncState(),
		customPrices: localItems
	});
	return {
		items: localItems,
		syncedWithBackend: false
	};
}
