function reconciliationBadge(status) {
	const s = status.toUpperCase();
	if (s === "MATCHED" || s === "RESOLVED") return {
		label: s === "MATCHED" ? "Khớp tự động" : "Đã đối soát",
		tone: "ok"
	};
	if (s === "UNDERPAID") return {
		label: "Chuyển thiếu",
		tone: "wait"
	};
	if (s === "OVERPAID") return {
		label: "Chuyển dư",
		tone: "wait"
	};
	if (s === "LATETRANSFER") return {
		label: "Chuyển muộn",
		tone: "wait"
	};
	if (s === "UNMATCHEDREFERENCE") return {
		label: "Sai mã tham chiếu",
		tone: "wait"
	};
	if (s === "REFUNDED" || s === "EXCESSREFUNDED") return {
		label: "Đã hoàn tiền",
		tone: "off"
	};
	return {
		label: status,
		tone: "todo"
	};
}
